alter table schedule_daily_overlays add column if not exists effective_class_ids uuid[];
alter table schedule_daily_overlays add column if not exists effective_subgroup_id uuid references class_subgroups(id) on delete set null;

create or replace function get_schedule_daily_effective_v2(p_date date default current_date) returns table(event_key text,source_schedule_id uuid,source_absence_lesson_id uuid,operation_group_id uuid,operation_kind text,teacher_id uuid,period smallint,class_ids uuid[],class_id uuid,class_name text,course_id uuid,subject text,classroom_id uuid,subgroup_id uuid,is_overlay boolean) language sql stable security definer set search_path=public as $$with base as(select 'S:'||ts.id::text,ts.id,al.id,null::uuid,case when al.id is not null then 'UNCOVERED' else 'BASE' end,ts.teacher_id,ts.period,array_remove(array[ts.class_id],null)::uuid[],ts.class_id,ts.class_name,ts.course_id,ts.subject,ts.classroom_id,ts.subgroup_id,false from teacher_schedule ts left join absence_lessons al on al.institution_code=ts.institution_code and al.source_schedule_id=ts.id and al.lesson_date=p_date where ts.active and tenant_row_allowed(ts.institution_code) and ts.weekday=extract(isodow from p_date)::smallint and not exists(select 1 from schedule_daily_overlays o where o.institution_code=ts.institution_code and o.overlay_date=p_date and o.status='ACTIVE' and o.source_schedule_id=ts.id)),ov as(select 'O:'||o.id::text,o.source_schedule_id,o.source_absence_lesson_id,o.operation_group_id,o.operation_kind,o.effective_teacher_id,o.effective_period,coalesce(o.effective_class_ids,array_remove(array[coalesce(o.effective_class_id,al.class_id,ts.class_id)],null)::uuid[]),coalesce(o.effective_class_id,al.class_id,ts.class_id),coalesce(o.effective_class_name,al.class_name,ts.class_name),coalesce(al.course_id,ts.course_id),coalesce(o.effective_subject,al.subject,ts.subject),coalesce(o.effective_classroom_id,al.classroom_id,ts.classroom_id),coalesce(o.effective_subgroup_id,al.subgroup_id,ts.subgroup_id),true from schedule_daily_overlays o left join absence_lessons al on al.id=o.source_absence_lesson_id left join teacher_schedule ts on ts.id=o.source_schedule_id where o.status='ACTIVE' and o.overlay_date=p_date and o.emits_event and tenant_row_allowed(o.institution_code)) select * from base union all select * from ov$$;

create or replace function assert_schedule_daily_overlay_hard_v1(p_date date) returns void language plpgsql security definer set search_path=public as $$declare r record;begin if exists(select 1 from get_schedule_daily_effective_v2(p_date)e where e.teacher_id is not null group by e.teacher_id,e.period having count(*)>1) then raise exception 'SUBSTITUTION_TEACHER_CONFLICT';end if;if exists(select 1 from get_schedule_daily_effective_v2(p_date)a join get_schedule_daily_effective_v2(p_date)b on a.event_key<b.event_key and a.period=b.period and a.class_ids&&b.class_ids and cardinality(a.class_ids)>0 and(a.subgroup_id is null or b.subgroup_id is null or a.subgroup_id=b.subgroup_id)) then raise exception 'SUBSTITUTION_CLASS_CONFLICT';end if;if exists(select 1 from get_schedule_daily_effective_v2(p_date)e where e.classroom_id is not null group by e.classroom_id,e.period having count(*)>1) then raise exception 'SUBSTITUTION_ROOM_CONFLICT';end if;if exists(select 1 from schedule_room_pools rp join classrooms c on c.room_pool_id=rp.id join get_schedule_daily_effective_v2(p_date)e on e.classroom_id=c.id where rp.active and tenant_row_allowed(rp.institution_code) group by rp.id,rp.max_simultaneous_activities,e.period having count(*)>rp.max_simultaneous_activities) then raise exception 'SUBSTITUTION_ROOM_POOL_SIMULTANEOUS_LIMIT';end if;if exists(with ev as(select e.*,s.unknown_count,s.student_count from get_schedule_daily_effective_v2(p_date)e left join lateral(select coalesce(bool_or(sc.imported_student_count is null),false) unknown_count,sum(coalesce(sc.imported_student_count,0)) student_count from unnest(e.class_ids)cid join school_classes sc on sc.id=cid)s on true) select 1 from schedule_room_pools rp join classrooms c on c.room_pool_id=rp.id join ev e on e.classroom_id=c.id where rp.active and rp.capacity is not null and tenant_row_allowed(rp.institution_code) group by rp.id,rp.capacity,e.period having bool_or(e.is_overlay) and bool_or(coalesce(e.unknown_count,false))) then raise exception 'SUBSTITUTION_ROOM_POOL_CAPACITY_UNKNOWN';end if;if exists(with ev as(select e.*,coalesce(s.student_count,0) student_count from get_schedule_daily_effective_v2(p_date)e left join lateral(select sum(coalesce(sc.imported_student_count,0)) student_count from unnest(e.class_ids)cid join school_classes sc on sc.id=cid)s on true) select 1 from schedule_room_pools rp join classrooms c on c.room_pool_id=rp.id join ev e on e.classroom_id=c.id where rp.active and rp.capacity is not null and tenant_row_allowed(rp.institution_code) group by rp.id,rp.capacity,e.period having bool_or(e.is_overlay) and sum(e.student_count)>rp.capacity) then raise exception 'SUBSTITUTION_ROOM_POOL_CAPACITY_EXCEEDED';end if;for r in select distinct teacher_id,period,classroom_id from get_schedule_daily_effective_v2(p_date) where teacher_id is not null and classroom_id is not null loop if cardinality(get_substitution_transfer_issues_v1(r.teacher_id,p_date,r.period,r.classroom_id))>0 then raise exception '%',(get_substitution_transfer_issues_v1(r.teacher_id,p_date,r.period,r.classroom_id))[1];end if;end loop;end$$;

create or replace function apply_schedule_daily_overlay_v1(p_date date,p_operations jsonb) returns jsonb language plpgsql security definer set search_path=public as $$declare op jsonb;k text;gid uuid:=gen_random_uuid();oid uuid;src_id uuid;al_id uuid;al absence_lessons%rowtype;ts teacher_schedule%rowtype;eff_teacher uuid;eff_period smallint;eff_class uuid;eff_classes uuid[];eff_room uuid;eff_subgroup uuid;eff_subject text;eff_class_name text;emit boolean;n int:=0;split_count int;join_count int;join_emit int;begin if not(is_manager_or_admin() or has_permission('schedule.edit')) then raise exception 'NOT_AUTHORIZED';end if;if jsonb_typeof(p_operations)<>'array' or jsonb_array_length(p_operations)=0 then raise exception 'OPERATIONS_REQUIRED';end if;select count(*) filter(where upper(x->>'operation_kind')='SPLIT'),count(*) filter(where upper(x->>'operation_kind')='JOIN'),count(*) filter(where upper(x->>'operation_kind')='JOIN' and coalesce((x->>'emits_event')::boolean,true)) into split_count,join_count,join_emit from jsonb_array_elements(p_operations)x;if split_count=1 then raise exception 'SPLIT_REQUIRES_MULTIPLE_PARTS';end if;if join_count>0 and(join_count<2 or join_emit<>1) then raise exception 'JOIN_REQUIRES_MULTIPLE_SOURCES_AND_ONE_EMIT';end if;perform pg_advisory_xact_lock(hashtext(current_tenant_code()||':'||p_date::text));for op in select * from jsonb_array_elements(p_operations) loop k:=upper(coalesce(op->>'operation_kind',''));if k not in('COVER','MOVE','SWAP','CANCEL','CREATE','SPLIT','JOIN') then raise exception 'INVALID_OPERATION_KIND';end if;src_id:=nullif(op->>'source_schedule_id','')::uuid;al_id:=nullif(op->>'source_absence_lesson_id','')::uuid;if al_id is not null then select * into al from absence_lessons where id=al_id and lesson_date=p_date and tenant_row_allowed(institution_code);if not found then raise exception 'ABSENCE_LESSON_NOT_FOUND';end if;if src_id is null then src_id:=al.source_schedule_id;end if;else al:=null;end if;if src_id is not null then select * into ts from teacher_schedule where id=src_id and active and tenant_row_allowed(institution_code);if not found then raise exception 'SOURCE_SCHEDULE_NOT_FOUND';end if;else ts:=null;end if;if k<>'CREATE' and src_id is null and al_id is null and coalesce((op->>'emit_only')::boolean,false)=false then raise exception 'SOURCE_REQUIRED';end if;eff_teacher:=coalesce(nullif(op->>'effective_teacher_id','')::uuid,case when al_id is not null then al.teacher_id else ts.teacher_id end);eff_period:=coalesce(nullif(op->>'effective_period','')::smallint,case when al_id is not null then al.period else ts.period end);eff_class:=coalesce(nullif(op->>'effective_class_id','')::uuid,case when al_id is not null then al.class_id else ts.class_id end);if op?'effective_class_ids' then select coalesce(array_agg(v::uuid),'{}'::uuid[]) into eff_classes from jsonb_array_elements_text(op->'effective_class_ids')v;else eff_classes:=array_remove(array[eff_class],null)::uuid[];end if;eff_room:=coalesce(nullif(op->>'effective_classroom_id','')::uuid,case when al_id is not null then al.classroom_id else ts.classroom_id end);eff_subgroup:=coalesce(nullif(op->>'effective_subgroup_id','')::uuid,case when al_id is not null then al.subgroup_id else ts.subgroup_id end);eff_subject:=coalesce(nullif(op->>'effective_subject',''),case when al_id is not null then al.subject else ts.subject end);eff_class_name:=coalesce(nullif(op->>'effective_class_name',''),case when al_id is not null then al.class_name else ts.class_name end);emit:=coalesce((op->>'emits_event')::boolean,k<>'CANCEL');if k='COVER' then if al_id is null or eff_teacher is null then raise exception 'COVER_REQUIRES_ABSENCE_AND_TEACHER';end if;if not exists(select 1 from get_substitute_candidates_v4(al_id)c where c.candidate_user_id=eff_teacher and c.feasible) then raise exception 'SUBSTITUTE_NOT_FEASIBLE';end if;end if;insert into schedule_daily_overlays(institution_code,overlay_date,operation_group_id,operation_kind,source_absence_lesson_id,source_schedule_id,effective_teacher_id,effective_period,effective_class_id,effective_class_ids,effective_classroom_id,effective_subgroup_id,effective_subject,effective_class_name,emits_event,payload,created_by) values(current_tenant_code(),p_date,gid,k,al_id,src_id,case when emit then eff_teacher else null end,case when emit then eff_period else null end,case when emit then eff_class else null end,case when emit then eff_classes else null end,case when emit then eff_room else null end,case when emit then eff_subgroup else null end,case when emit then eff_subject else null end,case when emit then eff_class_name else null end,emit,coalesce(op->'payload','{}'::jsonb),auth.uid()) returning id into oid;if k='COVER' then insert into substitute_assignments(absence_lesson_id,substitute_user_id,assigned_by,institution_code,overlay_id,reason,approval_status,approved_by,approved_at) values(al_id,eff_teacher,auth.uid(),current_tenant_code(),oid,coalesce(op->>'reason','V4 canonical cover'),'approved',auth.uid(),now()) on conflict(absence_lesson_id) do update set substitute_user_id=excluded.substitute_user_id,assigned_by=excluded.assigned_by,assigned_at=now(),overlay_id=excluded.overlay_id,reason=excluded.reason,approval_status='changed',approved_by=excluded.approved_by,approved_at=excluded.approved_at;end if;n:=n+1;end loop;perform assert_schedule_daily_overlay_hard_v1(p_date);update absences a set status='planned' where a.absence_date=p_date and tenant_row_allowed(a.institution_code) and not exists(select 1 from absence_lessons al left join substitute_assignments sa on sa.absence_lesson_id=al.id and sa.active where al.teacher_id=a.teacher_id and al.lesson_date=a.absence_date and tenant_row_allowed(al.institution_code) and sa.id is null);return jsonb_build_object('operation_group_id',gid,'operations',n);end$$;